.ds .ds-token-motion { position:relative; display:block; width:160px; height:24px; border:2px solid currentColor; border-radius:12px; }
.ds .ds-token-motion i { position:absolute; top:2px; left:2px; width:16px; height:16px; border-radius:50%; background:currentColor; transition:transform var(--p-duration); }
.ds .ds-token-motion:hover i { transform:translateX(136px); }
